package com.schoolmanagement.student;
import com.schoolmanagement.school.SchoolRepository; import com.schoolmanagement.classroom.*; import com.schoolmanagement.security.UserContext; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api/v1/students") public class StudentController { private final StudentRepository repo; private final SchoolRepository schools; private final ClassroomRepository classes; private final UserContext ctx; public StudentController(StudentRepository r,SchoolRepository s,ClassroomRepository c,UserContext u){repo=r;schools=s;classes=c;ctx=u;} public record Request(@NotBlank String admissionNumber,@NotBlank String firstName,@NotBlank String lastName,LocalDate dateOfBirth,Long classroomId){} @GetMapping public List<Student> list(){return repo.findAllBySchoolId(ctx.schoolId());} @GetMapping("/{id}") public Student get(@PathVariable Long id){return repo.findByIdAndSchoolId(id,ctx.schoolId()).orElseThrow(()->new NoSuchElementException("Student not found"));} @PostMapping public Student create(@Valid @RequestBody Request r){if(repo.existsBySchoolIdAndAdmissionNumber(ctx.schoolId(),r.admissionNumber()))throw new IllegalArgumentException("Admission number already exists");Student s=new Student();s.setSchool(schools.findById(ctx.schoolId()).orElseThrow());s.setAdmissionNumber(r.admissionNumber());s.setFirstName(r.firstName());s.setLastName(r.lastName());s.setDateOfBirth(r.dateOfBirth());if(r.classroomId()!=null)s.setClassroom(classes.findByIdAndSchoolId(r.classroomId(),ctx.schoolId()).orElseThrow(()->new NoSuchElementException("Class not found")));return repo.save(s);} @PutMapping("/{id}") public Student update(@PathVariable Long id,@Valid @RequestBody Request r){Student s=get(id);s.setFirstName(r.firstName());s.setLastName(r.lastName());s.setDateOfBirth(r.dateOfBirth());if(r.classroomId()!=null)s.setClassroom(classes.findByIdAndSchoolId(r.classroomId(),ctx.schoolId()).orElseThrow(()->new NoSuchElementException("Class not found")));return repo.save(s);} }
